const casos = [
  { peso_kg: 0.5,   valor_base_esperado: 25 },
  { peso_kg: 0.99,  valor_base_esperado: 25 },
  { peso_kg: 10,    valor_base_esperado: 25 },
  { peso_kg: 10.01, valor_base_esperado: 60 },
  { peso_kg: 50,    valor_base_esperado: 60 },
  { peso_kg: 50.01, valor_base_esperado: 110 },
  { peso_kg: 100,   valor_base_esperado: 110 },
  { peso_kg: 100.01,valor_base_esperado: 180 },
  { peso_kg: 1000,  valor_base_esperado: 180 }
];

function rodarCaso(index) {
  if (index >= casos.length) {
    return; // acabou a lista, encerra
  }

  const caso = casos[index];
  const body = {
    cliente: `Borda ${caso.peso_kg}kg`,
    peso_kg: caso.peso_kg,
    volumes: 5,
    uf_origem: 'SP',
    uf_destino: 'SP'
  };

  pm.sendRequest({
    url: `${pm.environment.get("url_base_v1")}/api/cotacoes`,
    method: 'POST',
    header: { 'Content-Type': 'application/json' },
    body: { mode: 'raw', raw: JSON.stringify(body) }
  }, function (err1, resV1) {
    if (err1) { console.error("Erro v1:", err1); return rodarCaso(index + 1); }

    const jsonV1 = resV1.json();

    pm.test(`v1 (peso ${caso.peso_kg}kg) - valor_base esperado`, function () {
      pm.expect(jsonV1.valor_base).to.eql(caso.valor_base_esperado);
    });

    pm.sendRequest({
      url: `${pm.environment.get("url_base_v2")}/api/cotacoes`,
      method: 'POST',
      header: { 'Content-Type': 'application/json' },
      body: { mode: 'raw', raw: JSON.stringify(body) }
    }, function (err2, resV2) {
      if (err2) { console.error("Erro v2:", err2); return rodarCaso(index + 1); }

      const jsonV2 = resV2.json();

      pm.test(`v2 (peso ${caso.peso_kg}kg) - valor_base esperado`, function () {
        pm.expect(jsonV2.valor_base).to.eql(caso.valor_base_esperado);
      });

      pm.test(`valor_base v1×v2 idêntico (peso ${caso.peso_kg}kg)`, function () {
        pm.expect(jsonV2.valor_base).to.eql(jsonV1.valor_base);
      });

      pm.test(`multiplicador v1×v2 idêntico (peso ${caso.peso_kg}kg)`, function () {
        pm.expect(jsonV2.multiplicador).to.eql(jsonV1.multiplicador);
      });

      rodarCaso(index + 1); // só avança pro próximo caso depois de terminar este
    });
  });
}

rodarCaso(0);

const jsonV1 = pm.response.json();

pm.test("v1 respondeu com sucesso", function () {
    pm.response.to.have.status(201);
});

// Busca a v2 pra comparar, usando a mesma cotação (id 10)
pm.sendRequest({
    url: `${pm.environment.get("url_base_v2")}/cotacoes/10`,
    method: 'GET'
}, function (err, resV2) {
    if (err) {
        console.error(err);
        return;
    }

    const jsonV2 = resV2.json();

    pm.test("valor_base da v2 é idêntico ao da v1", function () {
        pm.expect(jsonV2.valor_base).to.eql(jsonV1.valor_base);
    });

    pm.test("multiplicador da v2 é idêntico ao da v1", function () {
        pm.expect(jsonV2.multiplicador).to.eql(jsonV1.multiplicador);
    });
});
